// Demo: Signature UEFI PE32+ Image Loading — boot phase timeline
var phases=[['SEC',5],['PEI',40],['DXE',800],['BDS',300],['TSL',150],['RT',50]];
var t=0;console.log('technique: Signature UEFI PE32+ Image Loading');
phases.forEach(function(p){console.log(p[0]+': +'+p[1]+' ms (t='+t+' ms)');t+=p[1];});
console.log('total firmware time: '+t+' ms before OS handoff');

