// Demo: Signature Boot Services Memory Management — memory map sanity check
var descs=[];for(var i=0;i<16;i++){descs.push({type:(i*7+3)%4,start:i*4096,pages:1+((i*13)%8)});}
var ok=true;for(var i=1;i<descs.length;i++){if(descs[i].start<descs[i-1].start+descs[i-1].pages*4096)ok=false;}
console.log('technique: Signature Boot Services Memory Management');console.log('descriptors: '+descs.length);
console.log(ok?'memory map: no overlaps — safe to hand off':'memory map: OVERLAP — halt boot');

